const body=$input.first().json.body||$input.first().json;
// #12: mask PII (CCCD/SĐT/email) — LLM chỉ thấy bản masked, bản gốc giữ để audit.
const maskPii=(s)=>String(s||'').replace(/\b(\d{9}|\d{12})\b/g,'[MASKED_ID]').replace(/\b(0[35789]\d{8})\b/g,'[MASKED_PHONE]').replace(/[\w.-]+@[\w.-]+\.\w+/g,'[MASKED_EMAIL]');
return[{json:{originalMessage:body.message||body.originalMessage||'',maskedMessage:maskPii(body.maskedMessage||body.message||''),channel:body.channel||'web',employeeId:body.employeeId||null,sessionId:body.sessionId||null}}];

const answer = $("HR Agent").first().json.output;
const sessionId = $("Get/Create Session").first().json.id;
const employeeId = $("Normalize Input").first().json.employeeId;
return [{ json: { answer, sessionId, employeeId, intent: "HR_QA" } }];
